import { memo, useMemo } from 'react'
import type { Nutrition } from '@/types/recipe'
import {
  calculateTotalMacros,
  getMacroPercentage,
  formatServingType,
  getNutritionColor,
  getMacroLabel,
  getMacroIcon
} from '@/lib/nutrition-utils'

interface NutritionCardProps {
  nutrition: Nutrition
}

interface CircularProgressProps {
  percentage: number
  colorClass: string
  size?: number
  strokeWidth?: number
}

/**
 * Circular progress indicator component for displaying macro percentages
 */
function CircularProgress({
  percentage,
  colorClass,
  size = 100,
  strokeWidth = 8
}: CircularProgressProps) {
  const radius = (size - strokeWidth) / 2
  const circumference = 2 * Math.PI * radius
  const offset = circumference - (percentage / 100) * circumference

  return (
    <svg
      className="nutrition-circle-progress"
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      style={{ width: size, height: size }}
    >
      {/* Background circle */}
      <circle
        className="nutrition-circle-background"
        cx={size / 2}
        cy={size / 2}
        r={radius}
        strokeWidth={strokeWidth}
      />
      {/* Progress circle */}
      <circle
        className={`nutrition-circle-fill ${colorClass}`}
        cx={size / 2}
        cy={size / 2}
        r={radius}
        strokeWidth={strokeWidth}
        strokeDasharray={circumference}
        strokeDashoffset={offset}
      />
      {/* Percentage text */}
      <text
        className="nutrition-circle-text"
        x="50%"
        y="50%"
        dominantBaseline="middle"
        textAnchor="middle"
      >
        {percentage}%
      </text>
    </svg>
  )
}

/**
 * NutritionCard component displays nutrition information with visual indicators
 */
function NutritionCardComponent({ nutrition }: NutritionCardProps) {
  // Calculate total macros and percentages (memoized for performance)
  const macroData = useMemo(() => {
    const total = calculateTotalMacros(nutrition)
    return {
      protein: {
        amount: nutrition.protein,
        percentage: getMacroPercentage(nutrition.protein, total),
        colorClass: getNutritionColor('protein'),
        label: getMacroLabel('protein'),
        icon: getMacroIcon('protein')
      },
      carbs: {
        amount: nutrition.carbs,
        percentage: getMacroPercentage(nutrition.carbs, total),
        colorClass: getNutritionColor('carbs'),
        label: getMacroLabel('carbs'),
        icon: getMacroIcon('carbs')
      },
      fat: {
        amount: nutrition.fat,
        percentage: getMacroPercentage(nutrition.fat, total),
        colorClass: getNutritionColor('fat'),
        label: getMacroLabel('fat'),
        icon: getMacroIcon('fat')
      }
    }
  }, [nutrition])

  const servingLabel = formatServingType(nutrition.serving_type)

  return (
    <div className="nutrition-card" role="region" aria-label="Інформація про харчування">
      {/* Header */}
      <div className="nutrition-header">
        <span role="img" aria-label="nutrition">
          📊
        </span>
        <span>Харчова цінність</span>
      </div>

      {/* Calories Section */}
      <div className="nutrition-calories">
        <div className="nutrition-calories-value" aria-label={`${nutrition.calories} калорій`}>
          {nutrition.calories}
        </div>
        <div className="nutrition-calories-label">Калорії</div>
      </div>

      {/* Macros Grid */}
      <div className="nutrition-macros-grid">
        {/* Protein */}
        <div className="nutrition-macro-item">
          <CircularProgress
            percentage={macroData.protein.percentage}
            colorClass={macroData.protein.colorClass}
          />
          <div
            className="nutrition-macro-label"
            role="img"
            aria-label={macroData.protein.label}
          >
            <span>{macroData.protein.icon}</span>
            <span>{macroData.protein.label}</span>
          </div>
          <div
            className="nutrition-macro-value"
            aria-label={`${macroData.protein.amount} грам білків`}
          >
            {macroData.protein.amount}г
          </div>
        </div>

        {/* Carbs */}
        <div className="nutrition-macro-item">
          <CircularProgress
            percentage={macroData.carbs.percentage}
            colorClass={macroData.carbs.colorClass}
          />
          <div
            className="nutrition-macro-label"
            role="img"
            aria-label={macroData.carbs.label}
          >
            <span>{macroData.carbs.icon}</span>
            <span>{macroData.carbs.label}</span>
          </div>
          <div
            className="nutrition-macro-value"
            aria-label={`${macroData.carbs.amount} грам вуглеводів`}
          >
            {macroData.carbs.amount}г
          </div>
        </div>

        {/* Fat */}
        <div className="nutrition-macro-item">
          <CircularProgress
            percentage={macroData.fat.percentage}
            colorClass={macroData.fat.colorClass}
          />
          <div
            className="nutrition-macro-label"
            role="img"
            aria-label={macroData.fat.label}
          >
            <span>{macroData.fat.icon}</span>
            <span>{macroData.fat.label}</span>
          </div>
          <div
            className="nutrition-macro-value"
            aria-label={`${macroData.fat.amount} грам жирів`}
          >
            {macroData.fat.amount}г
          </div>
        </div>
      </div>

      {/* Serving Type Badge */}
      <div className="nutrition-serving-badge" role="note" aria-label={servingLabel}>
        <span role="img" aria-label="serving">
          🍽️
        </span>
        <span>{servingLabel}</span>
      </div>
    </div>
  )
}

// Memoize the component to prevent unnecessary re-renders
export const NutritionCard = memo(NutritionCardComponent)

